/* Original, read-only evidence drills. These extend the course catalog without
 * changing the tasks or IDs of previously completed lessons. */
function evidenceCommand(prompt,command,expected,explanation,hints){return {type:'command',evidence:true,prompt,command,expected,explanation,hints};}
function evidenceQuestion(prompt,correct,wrong,explanation,n=0){return choiceTask(prompt,correct,wrong,explanation,n);}
function addEvidenceLesson(id,stage,title,summary,terms,pages,tasks,quiz,source,video,parts){
 const n=hubCurriculum.opswork.length;
 hubCurriculum.opswork.push({id:'ops-evidence-'+id,opsStage:stage,evidenceLab:true,section:'命令找证据',title,summary,
  body:[summary,'从现象出发：确定范围 → 输入只读命令 → 读输出 → 判断证据 → 提出下一步。'],
  related:quiz[3],examples:tasks.filter(t=>t.type==='command').map(t=>({text:t.command,meaning:t.explanation})),
  tasks,quiz:evidenceQuestion(...quiz,n),source,videoReference:{video,parts},diagram:'',
  reminder:'先核对主机或集群、账号、命名空间与对象。提示按需展开；命令完成后还要读结果并手动确认。',
  transfer:quiz[3],teachingPages:[P('这次接到了什么问题？',[summary,'使用固定教学数据，不连接真实数据库、Docker 或 Kubernetes。通过步骤表示你完成了相应观察，不表示生产故障已经修复。']),
   {...P('先把本次术语讲清楚',[],'','',terms),termsOpen:true},...pages,
   P('操作路线：一步一条证据',['练习区先给任务，不直接展开整条答案。遇到困难依次看工具方向、参数提示和参考命令。补全只辅助输入，不执行命令。','执行成功后先看输出，再确认进入下一步；最终选择证据支持的结论。不会让你靠反复重启来碰运气。'])]});
}
addEvidenceLesson('mysql','database','实练：沿数据库身份找到一笔订单','订单页面显示异常。先确认 MySQL 连接，再定位 order_lab.orders 中 id=42 的记录。',
 ['数据库实例','主键','NULL'],[
 P('先核对连接身份',['客户端的连接配置、当前默认库和实际登录身份需要一起看。默认库可以为空，账号只能看到自己被允许访问的对象。','本课连接 db-lab:3306，默认库 order_lab，权限账号 reader@%。这都是教学设定，不是你的真实账户。']),
 P('数据库、表、列的查找顺序',['SHOW TABLES FROM order_lab 列出指定库的表；SHOW COLUMNS FROM order_lab.orders 观察该表字段。FROM 后不是文件路径，是数据库对象名。','SELECT 的投影列写在 FROM 前，WHERE 限定记录。分号是单条 SQL 结束符；本练习不支持多语句。']),
 P('按目标读取，不猜业务结果',['先核对 id 列，再读取 id=42 的 order_no 和 status。返回 PAID 只说明快照中的状态，不代表支付网关、退款和订单全链路已核验。','本地小型解释器仅支持已列出的单表 SELECT、等值 WHERE、SHOW TABLES/COLUMNS 与连接身份查询，不是完整 MySQL 引擎。'])],
 [evidenceCommand('确认当前默认数据库与权限账号。','SELECT DATABASE(), CURRENT_USER(), @@hostname, @@port;','reader@%',
  '默认库 order_lab；权限账号 reader@%；实例线索 db-lab:3306。还应和实际连接配置交叉核对。',
  ['使用 SELECT 读取当前连接的信息。','DATABASE() 看默认库；CURRENT_USER() 看权限账号；@@hostname 和 @@port 提供实例线索。']),
 evidenceCommand('列出 order_lab 数据库中的表。','SHOW TABLES FROM order_lab;','orders','表名 orders 和 order_items 都存在；看到表名还需要继续确认字段。',
  ['先列对象，不直接猜字段。','使用 SHOW TABLES，FROM 后指定 order_lab。']),
 evidenceCommand('查看 orders 表有哪些列。','SHOW COLUMNS FROM order_lab.orders;','order_no','id 是主键；order_no 为订单号；status 为状态。当前快照不包含其他业务系统字段。',
  ['查看表结构，不修改结构。','使用 SHOW COLUMNS，FROM 后给出库名.表名。']),
 evidenceCommand('只读取 id=42 这笔记录的订单号与状态。',"SELECT order_no, status FROM order_lab.orders WHERE id = 42;",'LAB-42',
  'LAB-42 的状态为 PAID。结果由本机教学数据计算；条件改成其他 id 会得到不同记录。',
  ['先列出需要读取的两列，再限定目标。','投影列是 order_no 和 status；FROM order_lab.orders；WHERE id = 42。']),
 evidenceQuestion('结果返回 PAID，哪种表述最准确？','教学记录 id=42 的 status 是 PAID，还需结合业务定义与其他证据',
  ['整个支付系统已经验收通过','所有订单都是 PAID'],'一个查询结果有明确对象和范围，不能外推整个系统。')],
 ['另一台实例也有 orders 表，怎样避免查错？','重新确认实例、数据库、账号和目标条件',['表名相同即可直接沿用结论','把 WHERE 去掉就更准确'],
  '迁移示例：接口展示字段可能经过计算；沿 SQL、库、表、列与目标记录定位，不从中文页面标题猜表名。'],
 ['MySQL SELECT 官方手册','https://dev.mysql.com/doc/refman/8.4/en/select.html'],'mysql',[1,17,26,28]);
addEvidenceLesson('docker-config','container','实练：容器退出，配置文件在哪里？','order-lab 启动后退出。用状态、日志和挂载信息判断下一步。',
 ['镜像','绑定挂载','退出状态'],[
 P('先发现已停止对象',['docker ps 默认主要展示运行中的容器；-a 或 --all 包含已停止对象。docker container ls 是同一命令的常见完整写法。','容器名与镜像名不同：本课容器叫 order-lab，镜像是 order-app:lab。']),
 P('日志与挂载分开读',['日志指出应用实际想读取的路径；inspect 可以核对挂载目标。两条证据对齐后，才判断是否路径错配。','inspect 的输出可能含环境凭据；真实工作分享前要脱敏。本课只有特制的无敏感信息字段。']),
 P('参数从左到右拆开',['docker logs --tail 20 order-lab：docker 是工具，logs 是读取日志的子命令，--tail 后的 20 是末尾行数，order-lab 是对象。','--tail=20 与 --tail 20 在本练习中等价。行数不同、对象不同不会被当成同一任务。'])],
 [evidenceCommand('列出包含已停止对象的容器列表。','docker ps -a','order-lab','order-lab 为 Exited (1)；其他容器可能仍运行，不能据此宣布宿主机全部故障。',
  ['要找的对象可能已经停止。','docker ps 需要包含全部状态的选项 -a 或 --all。']),
 evidenceCommand('读取 order-lab 最近 20 行日志。','docker logs --tail 20 order-lab','/app/config/app.yml',
  '应用尝试读取 /app/config/app.yml，但日志报告文件不存在。下一步对照实际挂载。',
  ['用 logs 子命令；不要先执行 restart。','--tail 指定行数 20，最后给容器名 order-lab。']),
 evidenceCommand('查看 order-lab 的状态与挂载配置。','docker inspect order-lab','/etc/order',
  'Source 是宿主机 /srv/order/config；Destination 是容器 /etc/order。应用却在读取 /app/config/app.yml，路径未对齐。',
  ['使用只读的对象详情查询。','inspect 后跟容器名 order-lab。']),
 evidenceQuestion('已有证据指向哪里？','应用读取路径与挂载目标不一致，需要核对配置方案',
  ['必须清空数据库','整个宿主机的硬盘必然损坏'],'日志给出读取路径，inspect 给出挂载目标，两条证据共同支持路径错配。',1)],
 ['修改挂载后，怎样才算验收完成？','确认容器内目标文件、账号权限和关键接口结果',['只看容器名字没有变化','只看命令没有输出'],
  '迁移示例：按变更计划修正来源与目标后，还要核验文件内容、权限、启动日志与业务接口；本课不执行真实修复。'],
 ['Docker 容器日志','https://docs.docker.com/reference/cli/docker/container/logs/'],'docker',[21,24,26,33]);
addEvidenceLesson('docker-port','container','实练：本机能访问，同事却打不开','web-lab 映射了端口。本机能打开页面，同事访问宿主机地址失败。',
 ['NAT','网关','绑定挂载'],[
 P('访问方向决定入口',['127.0.0.1 是访问者所在网络视图中的回环地址。浏览器中输入它是在访问浏览器所在设备，不是远程服务器。','发布到宿主机 127.0.0.1:8080 的端口，通常只提供宿主机本机入口；不能据此推断同事电脑可达。']),
 P('观察映射的三部分',['docker port web-lab 展示容器端口到宿主机地址端口的对应。80/tcp 是容器端口与协议，127.0.0.1:8080 是宿主机绑定入口。','改成对外监听之前，还要确认授权、访问来源、系统防火墙和云入口规则；不能为方便访问直接关闭全部规则。']),
 P('区分连接失败与应用错误',['连接拒绝、超时和 HTTP 500 代表不同阶段。先核对客户端访问的是谁，再看端口、监听与响应，不从一个现象跳到删库。'])],
 [evidenceCommand('读取 web-lab 的端口映射。','docker port web-lab','127.0.0.1:8080',
  '容器 80/tcp 映射到宿主机回环 127.0.0.1:8080，不是对所有网卡开放。',
  ['从实际映射取证，而不是猜端口。','docker port 后跟 web-lab。']),
 evidenceCommand('读取 web-lab 详情，核对宿主机绑定地址。','docker inspect web-lab','127.0.0.1',
  'HostIp=127.0.0.1，HostPort=8080；容器目标是 80/tcp。',
  ['查看 NetworkSettings.Ports 字段。','使用 inspect 子命令，对象是 web-lab。']),
 evidenceQuestion('同事在自己手机输入 127.0.0.1:8080，是在访问哪里？','手机自己的回环地址',['自动访问运行 Docker 的服务器','自动访问所有同事的电脑'],'回环地址属于访问者自己的网络视图。',2),
 evidenceQuestion('当前映射支持什么结论？','端口绑定在宿主机回环，需要按授权方案设计外部入口',['所有外部访问都应关闭防火墙来解决','Docker 镜像一定不存在'],'先把目标、地址绑定和允许的来源说清楚。',1)],
 ['若计划开放给指定同事，应该怎样做？','限定入口与来源，核对规则，再从目标客户端验证',['直接允许全网所有端口','只在服务器本机刷新页面'],
  '迁移示例：开放入口后从真正的目标客户端检查连通与业务响应；本机成功不能替代远端验收。'],
 ['Docker 端口映射','https://docs.docker.com/engine/network/port-publishing/'],'docker',[30,31]);
addEvidenceLesson('k8s-image','cluster','实练：ImagePullBackOff 先查哪条事件？','order 命名空间的一个 Pod 未启动。先确认上下文与范围，再看事件。',
 ['kubeconfig','命名空间','Pod'],[
 P('先确定自己在看哪套集群',['kubectl config current-context 给出当前上下文名。名字可以自定义，真实环境还应核对对应集群地址和身份；不要只根据名称推断安全。','本练习上下文 lab-cluster，命名空间 order-lab，目标 Pod order-abc。']),
 P('列表与详情各解决什么',['get pods 列状态，describe pod 汇总详情与事件。ImagePullBackOff 是镜像拉取失败后退避的状态线索，不是根因本身。','事件里的 manifest unknown 表明示例仓库未找到请求的镜像引用。还要核对标签、仓库、凭据与网络条件。']),
 P('接受等价的范围写法',['-n order-lab 与 --namespace=order-lab 都明确命名空间；pod 与 pods 是常见资源写法。选项可以在资源名前后，但对象范围必须保持一致。'])],
 [evidenceCommand('查看当前 kubectl 上下文。','kubectl config current-context','lab-cluster',
  '当前上下文是 lab-cluster。这是练习设定，不表示任何真实集群已连接。',
  ['先看连接范围，不做资源修改。','使用 config 的 current-context 子命令。']),
 evidenceCommand('列出 order-lab 命名空间的 Pod。','kubectl get pods -n order-lab','ImagePullBackOff',
  'order-abc 未就绪，状态 ImagePullBackOff；还需继续看事件取得具体原因。',
  ['用 get 查看 Pod 列表。','资源 pods；用 -n 或 --namespace 指定 order-lab。']),
 evidenceCommand('查看 order-abc 的详细事件，仍限定 order-lab。','kubectl describe pod order-abc -n order-lab','manifest unknown',
  '事件显示镜像 order-app:missing 拉取失败，仓库返回 manifest unknown。先核对镜像引用，不重启数据库。',
  ['用 describe 展开目标 Pod 的详情。','资源 pod，名称 order-abc；命名空间仍为 order-lab。']),
 evidenceQuestion('本快照直接支持的下一步是什么？','核对 order-app:missing 镜像引用及拉取配置',['扩容数据库硬盘','反复删除全部命名空间'],'状态指出阶段，事件进一步缩小原因；结论仍需验证。',1)],
 ['default 命名空间查不到 order-abc，能证明整个集群没有它吗？','不能，必须确认上下文与命名空间',['能，Pod 名在全球唯一','能，只要 kubectl 返回为空'],
  '迁移示例：实际 Pod、命名空间和上下文名称不同，先确定完整范围，再解释该环境事件。'],
 ['Kubernetes kubectl get','https://kubernetes.io/docs/reference/kubectl/generated/kubectl_get/'],'k8s',[24,25]);
addEvidenceLesson('k8s-service','cluster','实练：Service 有地址，为什么没有后端？','shop-lab 中 order Service 能解析，但请求失败。沿 Service、标签和就绪后端核验。',
 ['Service','selector','EndpointSlice'],[
 P('入口、选择器与后端是三层信息',['Service 对象存在不表示选中了健康 Pod。先读 selector，再列 Pod 标签和状态，最后查 EndpointSlice 的地址与就绪条件。','本练习 Pod 的 app 标签是 shop，而 Service selector 是 app=order。两端不匹配。']),
 P('端口别看反',['Service 的 port 是入口，targetPort 是后端端口。本课入口 80、后端 8080。标签不匹配时，即使端口正确也可能没有后端。','先取得可用后端，再继续检查监听、代理和实际请求，不把 DNS 能解析当成全链路完成。']),
 P('标签列表与结构化结果',['--show-labels 在列表中显示标签；-o yaml 用 YAML 展示对象。输出格式会改变，但命名空间、资源和对象必须保持正确。','EndpointSlice 的 kubernetes.io/service-name 标签用于关联具体 Service。示例空列表只说明本课指定范围内没有关联切片。'])],
 [evidenceCommand('查看 shop-lab 中 order Service 的配置。','kubectl get service order -n shop-lab -o yaml','app: order',
  'Service selector 为 app: order；port 为 80，targetPort 为 8080。',
  ['读取 Service 的配置，不修改对象。','get service order，指定 -n shop-lab 和 -o yaml。']),
 evidenceCommand('列出 shop-lab 的 Pod，并显示标签。','kubectl get pods -n shop-lab --show-labels','app=shop',
  'Pod order-web Ready=1/1，但标签 app=shop 与 Service 的 app=order 不匹配。',
  ['get pods 可以列出状态，另外请求显示标签。','命名空间 shop-lab；加 --show-labels。']),
 evidenceCommand('查看 shop-lab 中与 order Service 关联的 EndpointSlice。','kubectl get endpointslices -n shop-lab -l kubernetes.io/service-name=order','No resources found',
  '指定服务范围内没有 EndpointSlice。结合前面的标签错配，检查 Service 与 Pod 标签的设计。',
  ['get endpointslices；用标签条件限定到这个 Service。','-n shop-lab；-l kubernetes.io/service-name=order。']),
 evidenceQuestion('哪组证据支持标签错配？','Service selector=app:order，而 Pod label=app:shop',['只有 Service 名叫 order','只有 Pod 是 Running'],'比较两端实际值，不能仅凭名字或单独的状态。',2)],
 ['修正标签关系后还应验证什么？','后端就绪、目标监听与真实业务请求',['只看 YAML 缩进整齐','只看 DNS 仍能解析'],
  '迁移示例：若标签已经匹配却仍无后端，继续查就绪探针、命名空间和 EndpointSlice 条件，不能套用本题根因。'],
 ['Kubernetes Service 与后端','https://kubernetes.io/docs/concepts/services-networking/service/'],'k8s',[29,30,31]);
